-- CEP — DEVELOPMENT SEED DATA
-- Apply AFTER: CEP_Database_Schema.sql -> CEP_Database_Schema_Enterprise_Hardening.sql -> CEP_Database_Schema_SaaS_Tenancy.sql -> CEP_Database_Schema_Hybrid_Services.sql
--   psql -v ON_ERROR_STOP=1 -d cep_pool -f CEP_Seed_Data.sql
--
-- One fictional tenant ("Northwind Apparel", code NWA, subdomain northwind) on the GROWTH plan in the shared pool:
-- 4 users / 3 roles, 120 customers, 3 segments, 3 contact lists (master upload, dynamic, derived) with an import trail,
-- 12 personalization tags, 4 templates (email, SMS, MMS, e-receipt), governance policy + exemption, Postal & Digivize
-- providers with verified senders, a COMPLETED email campaign with recipient-level execution + webhooks, a SCHEDULED
-- SMS campaign, an ACTIVE e-receipt campaign, a welcome journey with enrollments and a journey-generated run,
-- consent / contact-point state, analytics rollups and metered usage.
--
-- RLS is FORCED, so the session must identify the tenant before any insert (a superuser bypasses RLS anyway):
-- Timestamps are absolute (Sept 2026) so the seed is reproducible; the partition block below creates the months it needs.
-- =====================================================================================
BEGIN;
SET app.current_tenant = 'a0000000-0000-4000-8000-000000000001';

-- Tenant registry row (partition_seq is assigned automatically)

-- Physical partitions for the tenant in this database: current + 3 months ahead, plus 3 months back for the seeded history
SELECT fn_provision_tenant('a0000000-0000-4000-8000-000000000001', 3);
DO $$
DECLARE r RECORD; v_part TEXT; v_child TEXT; v_month DATE;
BEGIN
    FOR r IN SELECT table_name FROM partition_retention_policy WHERE is_active AND tenant_partitioned AND sub_method = 'RANGE_MONTHLY' LOOP
        v_part := fn_tenant_partition_name(r.table_name, 'a0000000-0000-4000-8000-000000000001');
        FOR i IN 1 .. 3 LOOP
            v_month := (date_trunc('month', TIMESTAMPTZ '2026-09-16') - (i * INTERVAL '1 month'))::date;
            v_child := format('%s_%s', v_part, to_char(v_month, 'YYYY_MM'));
            IF to_regclass(v_child) IS NULL THEN
                EXECUTE format('CREATE TABLE %I PARTITION OF %I FOR VALUES FROM (%L) TO (%L)', v_child, v_part, v_month, (v_month + INTERVAL '1 month')::date);
            END IF;
        END LOOP;
    END LOOP;
END $$;





SET app.current_user_id = 'a1000000-0000-4000-8000-000000000001';





